```java
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>();
        list.add(1);
        list.add(2);
        list.add(3);

        try {
            System.out.println(checkList(list));
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }

    public static Integer checkList(List<Integer> list) throws IllegalArgumentException {
        if (list.isEmpty()) {
            return null;
        }

        List<Integer> distinctList = list.stream().distinct().collect(Collectors.toList());

        if (distinctList.size() > 1) {
            throw new IllegalArgumentException("List has more than one entry");
        }

        return distinctList.get(0);
    }
}
```

In this code, we first check if the list is empty. If it is, we return `null`. Then, we use Java Stream to get the distinct elements from the list. If the size of the distinct list is greater than 1, we throw an `IllegalArgumentException`. Otherwise, we return the first element of the distinct list.

Here is a simple program in Rust that reads URLs from a file, separates YouTube URLs from other URLs, and downloads the YouTube URLs using yt-dlp:

```rust
use std::fs::File;
use std::io::Read;
use std::io::Write;
use std::path::Path;
use std::process::Command;
use std::process::Read;

fn main() {
    let file = File::open("urls.txt").unwrap();
    let mut urls = String::new();

    while file.read_line(&mut urls).unwrap() {
        urls.push_str('\n');
    }

    let mut yt_urls = Vec::new();
    let mut other_urls = Vec::new();

    for url in urls.split('\n') {
        if url.contains("youtube.com") {
            yt_urls.push(url);
        } else {
            other_urls.push(url);
        }
    }

    for url in yt_urls {
        println!("Downloading YouTube: {}", url);
        Command::new("yt-dlp").arg(url).spawn();
    }

    for url in other_urls {
        println!("Downloading Other: {}", url);
        Command::new("yt-dlp").arg(url).spawn();
    }
}
```

This program reads URLs from a file named `urls.txt`, separates YouTube URLs from other URLs, and downloads the YouTube URLs using yt-dlp. It assumes that yt-dlp is installed and available in the system's PATH.

