```rust
use std::iter::Iterator;

fn main() {
    let mut = primes();
    for prime in mut {
        println!("{}", prime);
    }
}

fn primes() -> impl Iterator<Item = usize> {
    let mut n = 2;
    let mut primes = vec![];

    loop {
        if!is_prime(n, &primes) {
            n += 1;
            continue;
        }

        primes.push(n);
        yield n;
        n += 1;
    }
}

fn is_prime(n: usize, primes: &Vec<usize>) -> bool {
    for &prime in primes {
        if n % prime == 0 {
            return false;
        }
    }
    true
}
