  path: '/path/to/file',
  encoding: 'utf8'
});

stream.on('data', (chunk) => {
  console.log(chunk);
});

stream.on('error', (err) => {
  console.error(err);
});
```

In this example, we create a read stream that reads the contents of a file. The `data` event is emitted whenever a chunk of data is read from the file, and the `error` event is emitted if there is an error while reading the file.

You can also use the `readable` class to create a pull-based stream:

```javascript
const stream = require('stream');

const readable = stream.Readable({
  path: '/path/to/file',
  encoding: 'utf8'
});

readable.on('data', (chunk) => {
  console.log(chunk);
});

readable.on('error', (err) => {
  console.error(err);
});
```

In this example, we create a readable stream that reads the contents of a file. The `data` event is emitted whenever a chunk of data is read from the file, and the `error` event is emitted if there is an error while reading the file.

You can also use the `writable` class to create a pull-based stream:

```javascript
const stream = require('stream');

const writable = new Writable({
  path: '/path/to/file',
  encoding: 'utf8'
});

writable.on('data', (chunk) => {
  console.log(chunk);
});

writable.on('error', (err) => {
  console.error(err);
});
```

In this example, we create a writable stream that writes the contents of a file. The `data` event is emitted whenever a chunk of data is written to the file, and the `error` event is emitted if there is an error while writing to the file.

Note that a pull-based stream is different from a push-based stream. In a push-based stream, the data is pushed to the consumer, whereas in a pull-based stream, the consumer pulls the data from the stream. This means that a pull-based stream is more efficient than a push-based stream, as it avoids the overhead of pushing data that may not be needed.

