    return hiddenState;
  }

  outputLayer(hiddenState: number[]) {
    const output = Array(this.outputs);
    output.forEach((value, i) => {
      let sum = 0;
      for (let j = 0; j < this.hiddenSize; j++) {
        sum += this.weights[j][i] * hiddenState[j];
      }
      sum += this.biases[i];
      value = sigmoid.sigmoid(sum);
    });
    return output;
  }
}

class sigmoid {
  static sigmoid(x: number): number {
    return 1 / (1 + Math.exp(-x));
  }
}
```

