Here's a simple Flask web server with HTTP basic authentication using a Python dictionary for login/password, and an index page:

```python
from flask import Flask, request, make_response
from flask.auth import Basic_auth

app = Flask(__name__)

users = {
    "admin": "password",
    "user1": "password1",
    "user2": "password2"
}

@app.route("/")
def index():
    return "This is the index page."

@app.route("/protected")
def protected():
    return "This is the protected page."

@app.route("/login")
def login():
    return make_response("Please login in order to access the protected page.", 401)

@app.route("/logout")
def logout():
    return make_response("You have been logged out.", 200)

@app.route("/protected", methods=["GET", "POST"])
@Basic_auth
def protected():
    return "This is the protected page."

def basic_auth():
    auth = request.headers.get("Authorization")
    if auth:
        username, password = auth.split(":")
        if username in users and users[username] == password:
            return make_response("Access granted.", 200)
        else:
            return make_response("Access denied.", 401)
    else:
        return make_response("Access denied.", 401)

if __name__ == "__main__":
    app.run(debug=True)
```

